#!/bin/sh
# Generated by subscriber-engine for session 11111111-2222-3333-4444-555555555555. Runs Claude Code without a window or a person and records how it ended.
# Only validated values are substituted into this file; the repository is a quoted literal.
session='C:\appmod data\sessions\11111111-2222-3333-4444-555555555555'
# Claude Code that finds the variables of a parent Claude Code session (the engine was started from one) behaves as that session's child and does not keep
# its own conversation, so a later --resume finds nothing. Forget the variables that name a session; credentials and settings stay.
unset CLAUDECODE CLAUDE_CODE_CHILD_SESSION CLAUDE_CODE_SESSION_ID CLAUDE_CODE_SESSION_ATTENDED CLAUDE_CODE_ENTRYPOINT CLAUDE_CODE_SSE_PORT CLAUDE_CODE_MESSAGING_SOCKET CLAUDE_PID
repository='C:\work\r&d 100% ^'\''x (1) é\shop'
code=1
write_exit() {
    head=$(git -C "$repository" rev-parse HEAD 2>/dev/null)
    ended=$(date -u +%Y-%m-%dT%H:%M:%SZ)
    if [ -n "$head" ]; then head_json="\"$head\""; else head_json=null; fi
    printf '{"exitCode":%s,"endedAt":"%s","headEnd":%s}\n' "$code" "$ended" "$head_json" > "$session/exit.json.tmp" \
        && mv -f "$session/exit.json.tmp" "$session/exit.json"
}
trap write_exit EXIT
trap 'code=130; exit 130' INT
trap 'code=143; exit 143' TERM
cd "$repository" || exit 1
claude -p "Read and follow $session/prompt.md" --agent security-fixer --session-id 11111111-2222-3333-4444-555555555555 --name 'appmod fix 11111111' --allowedTools 'Read,Edit,Bash(git *),Bash(node *)' --disallowedTools 'Bash(curl *),Bash(git push *)' --add-dir "$session" --output-format stream-json --verbose
code=$?
exit $code
